from pyspark.sql import functions as F


def hba1c_band(observations, prediabetes_from, diabetes_from):
    value = F.col("value")
    band = (
        F.when(F.isnan(value), None)
        .when(value < prediabetes_from, "normal")
        .when(value < diabetes_from, "prediabetes")
        .when(value >= diabetes_from, "diabetes")
    )
    return observations.filter(F.col("code") == "HBA1C").select("observation_id", "value", band.alias("band"))


def solve(cutoffs):
    c = cutoffs.first()
    # Build the test input the rules describe and return what the step gives for it.
    test_input = spark.createDataFrame([], "observation_id STRING, code STRING, value DOUBLE")
    return hba1c_band(test_input, c.prediabetes_from, c.diabetes_from)
